<!-- RECENT PROJECTS (arrow carousel; hover or press a card to zoom) -->
<h2 id="projects" class="dd-wrap mb-0 mt-section text-balance text-center font-display text-[clamp(40px,6.1vw,88px)] font-bold leading-[1.1] tracking-tightest text-accent">Recent Projects</h2>
<p class="dd-wrap mb-0 mt-4 text-balance text-center text-[clamp(17px,1.4vw,20px)] font-normal leading-[1.6] tracking-[0.01em] text-ink max-w-[680px]">Real homes we’ve designed, from tropical retreats to timeless luxury.</p>
<div class="relative mt-[calc(var(--stack)-40px)] h-[calc(var(--card)+80px)] w-full shrink-0" data-gallery>
  <div class="dd-gallery-mask absolute inset-0 overflow-hidden" data-gallery-box>
    <div class="dd-scroll absolute inset-0 flex snap-x snap-mandatory items-center overflow-x-auto overflow-y-hidden" role="region" aria-label="Recent project gallery" tabindex="0" data-gallery-scroller>
      <figure class="dd-card m-0 snap-center overflow-hidden rounded-card" data-label="Modern Tropical House"><img class="block h-full w-full object-cover" src="assets/img/project-modern-tropical.jpg" srcset="assets/img/project-modern-tropical-480.jpg 480w, assets/img/project-modern-tropical.jpg 800w" sizes="(min-width: 1441px) 500px, (min-width: 750px) 34.7vw, 260px" width="800" height="1000" loading="lazy" decoding="async" alt="Modern Tropical House: open living and dining room under a timber roof, opening onto a pool and tropical garden"><figcaption class="dd-card-cap">Modern Tropical House</figcaption></figure>
      <figure class="dd-card m-0 snap-center overflow-hidden rounded-card" data-label="Japandi House"><img class="block h-full w-full object-cover" src="assets/img/project-japandi.jpg" srcset="assets/img/project-japandi-480.jpg 480w, assets/img/project-japandi.jpg 800w" sizes="(min-width: 1441px) 500px, (min-width: 750px) 34.7vw, 260px" width="800" height="1000" loading="lazy" decoding="async" alt="Japandi House: light living room with sheer curtains, cream sofa, oak dining table and rattan pendants"><figcaption class="dd-card-cap">Japandi House</figcaption></figure>
      <figure class="dd-card m-0 snap-center overflow-hidden rounded-card" data-label="Industrial Modern House"><img class="block h-full w-full object-cover" src="assets/img/project-industrial-modern.jpg" srcset="assets/img/project-industrial-modern-480.jpg 480w, assets/img/project-industrial-modern.jpg 800w" sizes="(min-width: 1441px) 500px, (min-width: 750px) 34.7vw, 260px" width="800" height="1000" loading="lazy" decoding="async" alt="Industrial Modern House: exposed concrete, black steel frames, grey sofa and Edison pendants"><figcaption class="dd-card-cap">Industrial Modern House</figcaption></figure>
      <figure class="dd-card m-0 snap-center overflow-hidden rounded-card" data-label="Modern Indonesian Heritage"><img class="block h-full w-full object-cover" src="assets/img/project-indonesian-heritage.jpg" srcset="assets/img/project-indonesian-heritage-480.jpg 480w, assets/img/project-indonesian-heritage.jpg 800w" sizes="(min-width: 1441px) 500px, (min-width: 750px) 34.7vw, 260px" width="800" height="1000" loading="lazy" decoding="async" alt="Modern Indonesian Heritage: teak living room with carved wood panels, rattan lantern and courtyard garden"><figcaption class="dd-card-cap">Modern Indonesian Heritage</figcaption></figure>
      <figure class="dd-card m-0 snap-center overflow-hidden rounded-card" data-label="Contemporary Luxury House"><img class="block h-full w-full object-cover" src="assets/img/project-contemporary-luxury.jpg" srcset="assets/img/project-contemporary-luxury-480.jpg 480w, assets/img/project-contemporary-luxury.jpg 800w" sizes="(min-width: 1441px) 500px, (min-width: 750px) 34.7vw, 260px" width="800" height="1000" loading="lazy" decoding="async" alt="Contemporary Luxury House: double-height living room with marble feature wall, walnut panels and glass chandelier"><figcaption class="dd-card-cap">Contemporary Luxury House</figcaption></figure>
      <div class="dd-scroll-end" aria-hidden="true"></div>
    </div>
  </div>

  <!-- CURSOR LABEL (follows the pointer over the gallery; hidden on touch screens) -->
  <div class="dd-pill pointer-events-none absolute left-1/2 top-1/2 z-[5] will-change-transform" aria-hidden="true" data-pill>
    <div class="dd-pill-inner inline-flex h-[76px] items-center justify-center gap-3.5 whitespace-nowrap rounded-full bg-white pl-[30px] pr-9 text-center font-sans text-[18px] font-medium uppercase tracking-[0.14em] text-accent shadow-[0_18px_40px_rgba(43,37,35,0.22),0_2px_6px_rgba(43,37,35,0.08)]"><span class="h-2.5 w-2.5 shrink-0 rounded-full bg-accent"></span><span data-pill-label></span></div>
  </div>
</div>

<!-- CAROUSEL ARROWS -->
<div class="-mt-4 flex w-full justify-center gap-3">
  <button type="button" class="dd-arrow flex h-11 w-11 cursor-pointer items-center justify-center rounded-full border border-accent bg-white p-0 text-accent hover:enabled:-translate-y-px hover:enabled:bg-accent hover:enabled:text-white sm:h-[52px] sm:w-[52px]" aria-label="Previous projects" disabled data-gallery-prev><svg class="h-[18px] w-[18px] sm:h-[22px] sm:w-[22px]" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M19 12H5"/><path d="M11 6l-6 6l6 6"/></svg></button>
  <button type="button" class="dd-arrow flex h-11 w-11 cursor-pointer items-center justify-center rounded-full border border-accent bg-white p-0 text-accent hover:enabled:-translate-y-px hover:enabled:bg-accent hover:enabled:text-white sm:h-[52px] sm:w-[52px]" aria-label="Next projects" data-gallery-next><svg class="h-[18px] w-[18px] sm:h-[22px] sm:w-[22px]" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14"/><path d="M13 6l6 6l-6 6"/></svg></button>
</div>
